function insideUploads(name) {
  if (typeof name !== "string" || name === "" || name.startsWith("/") || name.includes("\0")) return null;
  const parts = [];
  for (const segment of name.split("/")) {
    if (segment === "" || segment === ".") continue;
    if (segment === "..") {
      if (parts.length === 0) return null;
      parts.pop();
    } else {
      parts.push(segment);
    }
  }
  return parts.length === 0 ? null : parts.join("/");
}

for (const name of ["logo.png", "2026/./09/../logo.png", "2026/../../config/app.env", "/etc/hostname", "a/..", "a\0.png"]) {
  console.log(JSON.stringify(name), insideUploads(name));
