questions.solution:
function framing(headers) {
  const lengths = headers.filter(([name]) => name.toLowerCase() === "content-length").map(([, value]) => value);
  const encodings = headers.filter(([name]) => name.toLowerCase() === "transfer-encoding").map(([, value]) => value);
  if (lengths.length > 0 && encodings.length > 0) return "reject";
  if (encodings.length > 0) return encodings.length === 1 && encodings[0] === "chunked" ? "chunked" : "reject";
  if (lengths.length === 0) return "no body";
  if (!lengths.every((v) => /^\d+$/.test(v)) || new Set(lengths).size !== 1) return "reject";
  return `length ${Number(lengths[0])}`;
}

console.log(framing([["Content-Length", "12"]]));
console.log(framing([["transfer-encoding", "chunked"]]));
console.log(framing([["Content-Length", "12"], ["Transfer-Encoding", "chunked"]]));
console.log(framing([["content-length", "12"], ["Content-Length", "13"]]));
console.log(framing([["content-length", "12"], ["Content-Length", "12"]]));
