const FORBIDDEN = new Set(["__proto__", "constructor", "prototype"]);

function setByPath(target, path, value) {
  const parts = path.split(".");
  if (parts.length > 5 || parts.some((p) => p === "" || FORBIDDEN.has(p))) return false;
  let node = target;
  for (const part of parts.slice(0, -1)) {
    if (!Object.hasOwn(node, part) || typeof node[part] !== "object" || node[part] === null) {
      node[part] = Object.create(null);
    }
    node = node[part];
  }
  node[parts.at(-1)] = value;
  return true;
}

const prefs = Object.create(null);
console.log(setByPath(prefs, "display.theme", "dark"), JSON.stringify(prefs));
console.log(setByPath(prefs, "__proto__.isAdmin", true));
console.log(setByPath(prefs, "display.constructor.prototype.isAdmin", true));
console.log(setByPath(prefs, "a..b", 1), setByPath(prefs, "a.b.c.d.e.f", 1));
